import os
import tomllib


class ConfigError(Exception):
    def __init__(self, key: str, expected: str, value: str | None = None):
        self.key = key
        self.expected = expected
        self.value = value
        msg = f"{key}: expected {expected}, got {value!r}"
        super().__init__(msg)


def _merge_nested(base: dict, override: dict) -> dict:
    result = dict(base)
    for k, v in override.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = _merge_nested(result[k], v)
        else:
            result[k] = v
    return result


def _coerce(value: str, target: type) -> object:
    if target is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError("unknown", "int", value)
    if target is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError("unknown", "float", value)
    if target is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError("unknown", "bool", value)
    if target is str:
        return value
    raise ConfigError("unknown", repr(target), value)


