import os
import pytest
from envcfg import load_config, ConfigError


def test_defaults_only():
    defaults = {"a": 1, "b": 2}
    assert load_config(defaults) == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    defaults = {"a": 1, "b": 2}
    toml = {"a": 10, "c": 3}
    with open("/tmp/test_cfg.toml", "wb") as f:
        f.write(tomllib.dumps(toml).encode())
    result = load_config(defaults, toml_path="/tmp/test_cfg.toml")
    assert result == {"a": 10, "b": 2, "c": 3}


def test_env_overrides_toml():
    defaults = {"a": 1, "b": 2}
    toml = {"a": 10, "c": 3}
    with open("/tmp/test_cfg.toml", "wb") as f:
        f.write(tomllib.dumps(toml).encode())
    env = {"APP__A": "100", "APP__C": "400"}
    result = load_config(defaults, toml_path="/tmp/test_cfg.toml", env=env)
    assert result == {"a": 100, "b": 2, "c": 400}


def test_nested_toml():
    defaults = {"server": {"port": 8080, "host": "localhost"}}
    toml = {"server": {"port": 3000}}
    with open("/tmp/test_cfg.toml", "wb") as f:
        f.write(tomllib.dumps(toml).encode())
    result = load_config(defaults, toml_path="/tmp/test_cfg.toml")
    assert result["server"]["port"] == 3000
    assert result["server"]["host"] == "localhost"


def test_nested_env():
    defaults = {"server": {"port": 8080, "host": "localhost"}}
    env = {"APP__SERVER__PORT": "9000", "APP__SERVER__HOST": "example.com"}
    result = load_config(defaults, env=env)
    assert result["server"]["port"] == 9000
    assert result["server"]["host"] == "example.com"


def test_coerce_int_valid():
    defaults = {"port": 80}
    env = {"APP__PORT": "8080"}
    result = load_config(defaults, env=env)
    assert result["port"] == 8080


def test_coerce_int_invalid():
    defaults = {"port": 80}
    env = {"APP__PORT": "not-a-number"}
    with pytest.raises(ConfigError) as exc:
        load_config(defaults, env=env)
    assert "port" in str(exc.value)
    assert "int" in str(exc.value)


